const LevelGen = ({
}) => {
  const src = {
    // inputs
    lvlgen: makeAtom(eds.lvlgen.$src),
    prolog: makeAtom(eds.prolog.$src),

    // eval
    // lvlgen

    // outputs
    output: makeAtom(eds.output.$src),
    lvlgrid: makeAtom(eds.lvlgrid.$src),
  }
  const evaluating = {
    // outputs
    output: makeAtom(eds.output.$evaluating),
    lvlgrid: makeAtom(eds.lvlgrid.$evaluating),
  }
  const error = {
    // outputs
    output: makeAtom(eds.output.$error),
    lvlgrid: makeAtom(eds.lvlgrid.$error),
  }

  const evalID = 'lvlgen'
  useDebouncedEffect(() => {
    // terminate running workers
    if (evalID in WORKER_POOL)
      WORKER_POOL[evalID].forEach(w => w.terminate())

    // spawn new worker
    const evaluator = new Worker(new URL('Eval.js', import.meta.url))
    WORKER_POOL[evalID] = [evaluator]

    evaluate(evaluator,
             src,
             evaluating,
             error,
             [eds.lvlgen, eds.prolog], eds.lvlgen,
             [eds.output], {grid: eds.lvlgrid},
             evalID)
  },
  [src.lvlgen.val, src.prolog.val],
  100)

  return (
    <>
      <h2>
        Level Gen
        {techRow('js','pl')}
      </h2>
      <p>
        {/* {EdRef(eds.lvlgen)} & {EdRef(eds.prolog)} to {EdRef(eds.output)}.<br/> */}
        {/* The final level is shown in {EdRef(eds.lvlgrid)}<br/> */}
      </p>
      <div className='row'>
        <div className='col'>
          {eds.lvlgen.ed}
        </div>
        <div className='col'>
          {eds.prolog.ed}
        </div>
        <div className='col'>
          {eds.output.ed}
        </div>
        <div className='col'>
          {eds.lvlgrid.ed}
        </div>
      </div>
    </>
  )
}

