const Melofy = ({
}) => {
  // jotai
  const fullscreenWin = makeAtom($fullscreenWin)
  // const serverlog_src = makeAtom(eds.serverlog.$src)

  // const melofyWinRef = useRef(null)
  const iframeRef = useRef(null)
  const melofyLoaded = makeState(false)
  const melofyEvaling = makeState(false)
  const melofyFullscreend = fullscreenWin.val?.current?.id == 'window_melofy.melofy.dev' // FIXME
  const melofyEvalingTooltip = makeState('Loading...')
  const melofyIframeStyle = {
    marginBottom: '-5px',
    border: 'none',
    width: melofyFullscreend ? '100%' : '774px',
    height: melofyFullscreend ? 'calc(100% - 22px)' : '600px',
  }

  // tools
  const onReset = useCallback(() => {
    if (iframeRef.current != null) {
      log('iframeref',iframeRef)
      // iframeRef.current.src += ''
      iframeRef.current.src = iframeRef.current.src
    }
  }, [iframeRef])
  const tools = {
    reset: toolButton({
      id: 'reset',
      title: 'Refresh',
      icon:  faArrowRotateLeft,
      click: onReset,
      // invert: highlight.val,
    }),
  }
  const addTools = [tools.reset]

  return (
    <>
      <h2>
        Melofy
        {techRow('js','py','pytorch','flask')}
      </h2>
      {/* <p>Generates exercise workout routine using {EdRef(eds.Main)}, {EdRef(eds.BlockGroup)}.<br/></p> */}
      <div className='row'>
        <KeyMap grid={[
          [['Delete Track','x',false], ['Play / Pause','space',false,' '], ['Upload File','u',false,]],
        ]} />
      </div>
      <div className='row'>
        <div className='col'>
          <Win
            // ref={melofyWinRef}
            title='melofy.melofy.dev'
            evaluating={!melofyLoaded.val || melofyEvaling.val}
            evaluatingTooltip={melofyEvalingTooltip.val}
            winbodystyle={{
              backgroundColor: '#161525',
            }}
            addTools={addTools}
            content={(
              <iframe
                ref={iframeRef}
                src='https://melofy.melofy.dev/'
                style={melofyIframeStyle}
                onLoad={() => melofyLoaded.set(true)}
              />
            )}
          />
        </div>
        {/* <div className='col'>
          {eds.serverlog.ed}
        </div> */}
      </div>
    </>
  )
}

