const BlurOverlay = ({
}) => {
  const fullscreenWin = makeAtom($fullscreenWin)

  return (
    <>
      {fullscreenWin.val && (
        <div
          style={{
            position: 'fixed',
            zIndex: 99,
            left: 0,
            top: 0,
            right: 0,
            bottom: 0,
            
            // performant light
            // background: 'rgba(255,255,255,0.8)',

            // performant dark
            // background: 'rgba(0,0,0,0.65)',

            // performant solid
            background: 'rgb(255,255,255)',

            // stylin
            // background: 'rgba(0,0,0,0)',
            // backdropFilter: 'blur(10px)'
          }}
          onClick={() => fullscreenWin.set(null)}
        />
      )}
    </>
  )
}

